SET LOCAL lock_timeout = '2s';
CREATE TABLE action_inbox_snoozes (
    org_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    account_id UUID NOT NULL,
    item_id TEXT NOT NULL CHECK (char_length(item_id) BETWEEN 3 AND 200),
    until DATE NOT NULL,
    item_version TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- No reference to users: a group administrator acting in this tenant has their user row in another one.
    PRIMARY KEY (org_id, account_id, item_id)
);
ALTER TABLE action_inbox_snoozes ENABLE ROW LEVEL SECURITY;
ALTER TABLE action_inbox_snoozes FORCE ROW LEVEL SECURITY;
CREATE POLICY org_isolation ON action_inbox_snoozes
    USING (org_id = NULLIF(current_setting('app.current_org', true), '')::uuid)
    WITH CHECK (org_id = NULLIF(current_setting('app.current_org', true), '')::uuid);
REVOKE ALL ON action_inbox_snoozes FROM PUBLIC, console_rt;
GRANT SELECT, INSERT, UPDATE, DELETE ON action_inbox_snoozes TO console_rt;
COMMENT ON TABLE action_inbox_snoozes IS 'Inbox items an account postponed in its own view; never changes the item or what others see';
COMMENT ON COLUMN action_inbox_snoozes.org_id IS 'pd:none — tenant boundary';
COMMENT ON COLUMN action_inbox_snoozes.account_id IS 'pd:personal — account that postponed the item';
COMMENT ON COLUMN action_inbox_snoozes.item_id IS 'pd:personal — which inbox item the account postponed';
COMMENT ON COLUMN action_inbox_snoozes.until IS 'pd:personal — date the item returns to the account''s list';
COMMENT ON COLUMN action_inbox_snoozes.item_version IS 'pd:none — the item''s decision version when it was postponed';
COMMENT ON COLUMN action_inbox_snoozes.created_at IS 'pd:personal — when the account postponed the item';
